def largestGood(binString: str) -> str:
    pieces, bal, start = [], 0, 0
    for i, c in enumerate(binString):
        bal += 1 if c == '1' else -1
        if bal == 0:
            inner = binString[start + 1:i]
            pieces.append('1' + largestGood(inner) + '0')
            start = i + 1
    pieces.sort(reverse=True)
    return ''.join(pieces)

import java.util.*;

class Solution {
    String largestGood(String binString) {
        List<String> pieces = new ArrayList<>();
        int bal = 0, start = 0;
        for (int i = 0; i < binString.length(); i++) {
            bal += binString.charAt(i) == '1' ? 1 : -1;
            if (bal == 0) {
                pieces.add("1" + largestGood(binString.substring(start + 1, i)) + "0");
                start = i + 1;
            }
        }
        pieces.sort(Comparator.reverseOrder());
        return String.join("", pieces);
    }
}

class Solution {
public:
    string largestGood(string binString) {
        vector<string> pieces;
        int bal = 0, start = 0;
        for (int i = 0; i < (int)binString.size(); ++i) {
            bal += binString[i] == '1' ? 1 : -1;
            if (bal == 0) {
                pieces.push_back("1" + largestGood(binString.substr(start + 1, i - start - 1)) + "0");
                start = i + 1;
            }
        }
        sort(pieces.rbegin(), pieces.rend());
        string res;
        for (auto& p : pieces) res += p;
        return res;
    }
};
